// The module of the R4 measurement (tests/context-budget-packet-scope.test.mjs): an O11 Reactive module "Pedidos" as its
// kernel reader writes it (ssam-digest/1; every block text copied in form from real digests of .local/module-index: the
// entity, static entity with records, structure, site property and client variable, exception, timer, REST consumed, role,
// screen with locals, aggregate, actions and widgets, block with inputs), the flow reading of Pedido_Create (ssam-flow/1 with
// @ids) and the ssam-html/1 reading of PedidoLista (k on every element). Nothing here is read from a Studio.
import { createHash } from 'node:crypto';
import { DIGEST_EXTRACTOR, DIGEST_SECTIONS } from '../../../module-digest.mjs';
import { textSha } from '../../../module-flow.mjs';

export const SOURCE_SHA = createHash('sha256').update('Pedidos fixture capture r4').digest('hex');
export const FILE = 'C:\\captures\\Pedidos.oml';
const block = (key, kind, name, text, extra = {}) => ({ key, kind, name, text, ...extra });
const action = (key, kind, name, inp, out, calls = [], calledBy = [], extra = {}) => ({ key, kind, name, section: 'actions', public: false, function: false, in: inp, out, calls, calledBy, ...extra });

export const ACTIONS = [
  action('A1', 'ServerAction', 'Pedido_Create', 'Pedido: PedidoDados', 'PedidoId: Pedido Identifier', ['CreatePedido', 'Pedido_Validate'], ['PedidoCadastroSalvar']),
  action('A2', 'ServerAction', 'Pedido_Validate', 'Pedido: PedidoDados', 'IsValid: Boolean', [], ['Pedido_Create']),
  action('A3', 'ServerAction', 'Pedido_Delete', 'PedidoId: Pedido Identifier', '', ['DeletePedido'], []),
  action('A4', 'ServerAction', 'Pedido_GetTotal', 'PedidoId: Pedido Identifier', 'Total: Decimal', ['GetPedido'], []),
  action('A5', 'ServerAction', 'Cliente_Get', 'ClienteId: Cliente Identifier', 'Cliente: Cliente', ['GetCliente'], []),
  action('A6', 'ServerAction', 'Cliente_AtualizarEndereco', 'ClienteId: Cliente Identifier; Cep: Text', '', ['UpdateCliente'], []),
  action('A7', 'ServerAction', 'Pedido_LimparAbandonados', '', 'Removidos: Integer', [], []),
  ...Array.from({ length: 30 }, (_, i) => action('B' + i, 'ServerAction', 'Relatorio_' + String(i).padStart(2, '0'), 'Filtro: Text; Inicio: Date', 'Total: Integer', [], [])),
];

const actionBody = a => a.name === 'Pedido_Create'
  ? 'server action Pedido_Create @A1\n  in Pedido: PedidoDados\n  out PedidoId: Pedido Identifier\n  Pedido_Validate = Pedido_Validate(Pedido)\n  if not Pedido_Validate.IsValid:  # Pedido inválido?\n    raise PedidoInvalido("Pedido inválido")\n  CreatePedido = CreatePedido(Source=Pedido)\n  PedidoId = CreatePedido.Id'
  : 'server action ' + a.name + ' @' + a.key + (a.in ? '\n  in ' + a.in : '') + (a.out ? '\n  out ' + a.out : '') + '\n  end';

export function digest(lane = 'o11') {
  const sections = {
    module: { title: 'module and references', count: 3, blocks: [
      block('R0', 'ESpace', 'Pedidos', 'ssam-digest/1 module=Pedidos type=Reactive lane=' + lane + ' key=@R0 sourceSha256=' + SOURCE_SHA + ' elements=640'),
      block('RS', 'Reference', '(System)', 'reference (System) @RS (Reactive)\n  ServerAction: CommitTransaction, ListAppend, ListFilter, ListIndexOf, LogMessage\n  ServerEntity: User'),
      block('RU', 'Reference', 'OutSystemsUI', 'reference OutSystemsUI @RU (Reactive)\n  WebBlock: LayoutTopMenu, Menu, Pagination, Search, Tag, Card, CardSectioned\n  ClientAction: FeedbackMessageShow, ToggleSideMenu'),
    ] },
    entities: { title: 'entities', count: 5, blocks: [
      block('E1', 'ServerEntity', 'Pedido', 'entity Pedido @E1 public "Um pedido de venda."\n  Id: Long Integer req auto\n  ClienteId: Cliente Identifier req ->Cliente delete=Protect\n  StatusPedidoId: StatusPedido Identifier req ->StatusPedido delete=Protect\n  Total: Decimal(18,2) req\n  CriadoEm: Date Time\n  indexes generated by the platform: 2'),
      block('E2', 'ServerEntity', 'PedidoItem', 'entity PedidoItem @E2 public\n  Id: Long Integer req auto\n  PedidoId: Pedido Identifier req ->Pedido delete=Delete\n  ProdutoId: Produto Identifier req ->Produto delete=Protect\n  Quantidade: Integer req\n  Preco: Decimal(18,2)'),
      block('E3', 'ServerEntity', 'Cliente', 'entity Cliente @E3 public\n  Id: Long Integer req auto\n  Nome: Text(200) req\n  Email: Email\n  Cep: Text(9)'),
      block('E4', 'ServerEntity', 'Produto', 'entity Produto @E4 public\n  Id: Long Integer req auto\n  Nome: Text(200) req\n  Preco: Decimal(18,2) req'),
      block('E5', 'StaticEntity', 'StatusPedido', 'static entity StatusPedido @E5 public read-only "Estados do pedido."\n  Id: Long Integer req\n  Label: Text(50)\n  Order: Integer\n  Is_Active: Boolean\n  record Aberto: Id=1, Is_Active=True, Label="Aberto", Order=1\n  record Cancelado: Id=3, Is_Active=True, Label="Cancelado", Order=3\n  record Fechado: Id=2, Is_Active=True, Label="Fechado", Order=2', { records: 3 }),
    ] },
    structures: { title: 'structures', count: 2, blocks: [
      block('T1', 'Structure', 'PedidoDados', 'structure PedidoDados @T1 public\n  ClienteId: Cliente Identifier; Total: Decimal(18,2); Itens: PedidoItem List'),
      block('T2', 'Structure', 'ViaCepResposta', 'structure ViaCepResposta @T2\n  cep: Text; logradouro: Text; bairro: Text; localidade: Text; uf: Text'),
    ] },
    variables: { title: 'site properties and client/session variables', count: 3, blocks: [
      block('V1', 'SiteProperty', 'MaxItensPorPedido', 'site property MaxItensPorPedido @V1: Integer =50'),
      block('V2', 'SiteProperty', 'TenantId', 'site property TenantId @V2: Tenant Identifier read-only "Current Tenant identifier generated by the Platform."'),
      block('V3', 'ClientVariable', 'UltimoFiltro', 'client variable UltimoFiltro @V3: Text'),
    ] },
    roles: { title: 'roles', count: 1, blocks: [block('RO1', 'Role', 'Vendedor', 'role Vendedor @RO1 public persistent "Cria e acompanha pedidos."')] },
    exceptions: { title: 'user exceptions', count: 1, blocks: [block('X1', 'UserException', 'PedidoInvalido', 'exception PedidoInvalido @X1')] },
    actions: { title: 'actions', count: ACTIONS.length, blocks: ACTIONS.map(a => block(a.key, a.kind, a.name, actionBody(a))) },
    timers: { title: 'timers', count: 1, blocks: [block('TM1', 'Timer', 'RecalcularTotais', 'timer RecalcularTotais @TM1 action=Pedido_GetTotal priority=Normal timeout=20min')] },
    integrations: { title: 'REST and SOAP, consumed and exposed', count: 1, blocks: [
      block('I1', 'RestClient', 'ViaCep', 'rest consumed ViaCep @I1 BaseURL=https://viacep.com.br/ws\n  GET /{cep}/json rest action ConsultarCep @I1a'),
    ] },
    ui: { title: 'screens, blocks and emails', count: 3, blocks: [
      block('S1', 'MobileScreen', 'PedidoLista', ['screen MainFlow/PedidoLista @S1 roles=Vendedor title="Pedidos"',
        '  local SearchText: Text; StartIndex: Integer; MaxRecords: Integer =20',
        '  aggregate GetPedidos @S1g fetch=AtStart = FROM Pedido, Cliente JOIN Inner Pedido~Cliente ON Pedido.ClienteId = Cliente.Id WHERE (SearchText = "" or Cliente.Nome like "%" + SearchText + "%") SORT Pedido.CriadoEm desc MAX 20',
        '  action Buscar @S1a1',
        '    GetPedidos = refresh GetPedidos',
        '  action AbrirPedido @S1a2',
        '  widgets:',
        '    block LayoutTopMenu()  # inside [Header] @S1h, [Title] @S1t',
        '      [MainContent] @S1m:',
        '        input SearchInput @S1w1 var=SearchText',
        '        button BuscarButton @S1w2 "Buscar" on OnClick->Buscar',
        '        table PedidosTable @S1w3 source=GetPedidos.List',
        '          expr Cliente.Nome',
        '          expr Pedido.Total',
      ].join('\n')),
      block('S2', 'MobileScreen', 'PedidoDetalhe', 'screen MainFlow/PedidoDetalhe @S2 roles=Vendedor\n  in PedidoId: Pedido Identifier\n  aggregate GetPedidoById @S2g fetch=AtStart = FROM Pedido WHERE (Pedido.Id = PedidoId) MAX 1\n  widgets:\n    block LayoutTopMenu()\n      [MainContent] @S2m:\n        expr GetPedidoById.List.Current.Pedido.Total'),
      block('B1', 'MobileBlock', 'PedidoCard', 'block Common/PedidoCard @B1 public\n  in PedidoId: Pedido Identifier; Destaque?: Boolean\n  widgets:\n    container CardWrapper @B1w1\n      expr PedidoId'),
    ] },
    coverage: { title: 'coverage', count: 640, blocks: [block('R0', 'ESpace', 'coverage', 'elements 640: rendered 640')] },
  };
  return { schema: 'ssam-digest/1', extractor: DIGEST_EXTRACTOR, lane, adapter: 'kernel', sourceSha256: SOURCE_SHA, sourceBytes: 128000, createdAt: '2026-10-24T00:00:00Z',
    module: { name: 'Pedidos', key: 'R0', kind: 'Reactive' }, elements: 640, notRendered: 0, clipped: 0, readErrors: 0,
    sections: DIGEST_SECTIONS.map(id => ({ id, ...sections[id] })), actions: ACTIONS };
}
export const found = (lane = 'o11') => ({ ok: true, lane, target: FILE, file: FILE, sourceSha256: SOURCE_SHA, module: { name: 'Pedidos' }, digest: digest(lane) });

// The flow reading of Pedido_Create (ssam-flow/1 as view "flow" serves it: @key on the header, @n nodes, @p parameters).
export const FLOW_TEXT = ['/// Cria um pedido depois de validá-lo.',
  'server action Pedido_Create @A1',
  '  in Pedido: PedidoDados @p1',
  '  out PedidoId: Pedido Identifier @p2',
  '  Pedido_Validate = Pedido_Validate(Pedido=Pedido) @n1',
  '  if not Pedido_Validate.IsValid:  # Pedido inválido? @n2',
  '    raise PedidoInvalido("Pedido inválido") @n3',
  '  CreatePedido = CreatePedido(Source=Pedido) @n4',
  '  assign  # Devolve o id @n5',
  '    PedidoId = CreatePedido.Id',
  '  end @n6', ''].join('\n');
export const FLOW_READING = { kind: 'flow', name: 'Pedido_Create', key: 'A1', textSha: textSha(FLOW_TEXT), fixedPoint: true, text: FLOW_TEXT };

// The ssam-html/1 reading of PedidoLista (view "html"): k on every element, its basedOn {capture, html}.
export const HTML_TEXT = ['<screen name="PedidoLista" actions="Buscar, AbrirPedido" roles="Vendedor" title=\'"Pedidos"\'>',
  '<var k="w1" name="SearchText" type="Text"/>',
  '<var k="w2" name="StartIndex" type="Integer"/>',
  '<aggregate k="w3" name="GetPedidos" from="Pedido" join="Cliente on Pedido.ClienteId = Cliente.Id" sort="Pedido.CriadoEm desc" max="20"/>',
  '<Block k="w4" name="LayoutTopMenu">',
  ' <slot name="MainContent">',
  '  <input k="w5" id="SearchInput" bind="SearchText" class="form-control"/>',
  '  <button k="w6" id="BuscarButton" class="btn btn-primary" onclick="Buscar">Buscar</button>',
  '  <div k="w7" id="PedidosTable" list="GetPedidos.List">',
  '   <div k="w8">{{ GetPedidos.List.Current.Cliente.Nome }}</div>',
  '   <div k="w9">{{ GetPedidos.List.Current.Pedido.Total }}</div>',
  '  </div>',
  ' </slot>',
  '</Block>',
  '</screen>', ''].join('\n');
export const HTML_SHA = createHash('sha256').update(HTML_TEXT).digest('hex');
export const HTML_READING = { kind: 'html', screen: 'PedidoLista', key: 'S1', basedOn: { capture: SOURCE_SHA, html: HTML_SHA }, html: HTML_TEXT };

// The owner reader of discovery.mjs (laneOwner's shape): the readings of the targets the packet asks for.
export const ownerReader = calls => async request => {
  calls?.push(request);
  // Pedido_Create and PedidoLista as above; any other action as the reader would serve it (its header, signature, end).
  const other = t => { const x = ACTIONS.find(y => y.key === t.key); if (!x) return null;
    const text = ['server action ' + x.name + ' @' + x.key, ...(x.in ? x.in.split('; ').map((p, i) => '  in ' + p + ' @p' + (i + 1)) : []), '  end @n1', ''].join('\n');
    return { kind: 'flow', name: x.name, key: x.key, textSha: textSha(text), fixedPoint: true, text }; };
  const readings = request.targets.map(t => t.kind === 'flow' && t.key === 'A1' ? FLOW_READING : t.kind === 'html' && t.key === 'S1' ? HTML_READING : t.kind === 'flow' ? other(t) : null).filter(Boolean);
  return { ok: true, readings, errors: [] };
};
